from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); obj=[]
        while q:
          x,y=q.pop(); obj.append((x,y))
          for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]!=bg:
              seen.add((a,b)); q.append((a,b))
        comps.append(obj)
    motif=max(comps,key=len)
    r0=min(r for r,c in motif); r1=max(r for r,c in motif)
    c0=min(c for r,c in motif); c1=max(c for r,c in motif)
    # Empirical marker-to-stamp anchor remains ambiguous across demos.
    ar,ac=(r0+r1)//2,(c0+c1)//2
    markers=[p for obj in comps if obj is not motif for p in obj]
    out=[row[:] for row in grid]
    for mr,mc in markers:
      for r in range(r0,r1+1):
        for c in range(c0,c1+1):
          if grid[r][c]==bg: continue
          rr,cc=mr+r-ar,mc+c-ac
          if 0<=rr<h and 0<=cc<w: out[rr][cc]=grid[r][c]
    return out
